package patches.vcsRoots

import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.ui.*
import jetbrains.buildServer.configs.kotlin.vcs.GitVcsRoot

/*
This patch script was generated by TeamCity on settings change in UI.
To apply the patch, change the vcsRoot with id = 'CxxCiDemo_Main_DemoProjectB'
accordingly, and delete the patch script.
*/
changeVcsRoot(RelativeId("CxxCiDemo_Main_DemoProjectB")) {
    val expected = GitVcsRoot({
        id("CxxCiDemo_Main_DemoProjectB")
        name = "demo-project-b"
        url = "http://gitlab.local:8929/root/demo-project-b.git"
        branch = "%branch_default%"
        branchSpec = "%branch_spec%"
        checkoutPolicy = GitVcsRoot.AgentCheckoutPolicy.NO_MIRRORS
        authMethod = password {
            userName = "root"
            password = "%gitlab_credentials_password%"
        }
    })

    check(this == expected) {
        "Unexpected VCS root settings"
    }

    (this as GitVcsRoot).apply {
        authMethod = password {
            userName = "root"
            password = "credentialsJSON:f334f54e-6d8a-48a8-aa0d-117995e9bb37"
        }
    }

}
